import{_ as a,o as n,c as t,a2 as r}from"./chunks/framework.xeBd2WE1.js";const m=JSON.parse('{"title":"AI 动态 · 2026-09-15","description":"","frontmatter":{"title":"AI 动态 · 2026-09-15","date":"2026-09-15T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-09/ai-news-2026-09-15.md","filePath":"news/2026-09/ai-news-2026-09-15.md","lastUpdated":null}'),s={name:"news/2026-09/ai-news-2026-09-15.md"};function o(i,e,l,c,p,d){return n(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-09-15" tabindex="-1">AI 动态 · 2026-09-15 <a class="header-anchor" href="#ai-动态-·-2026-09-15" aria-label="Permalink to &quot;AI 动态 · 2026-09-15&quot;">​</a></h1><blockquote><p>截至 2026-09-15。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="openai、anthropic、google-就-ai-安全密谈数周" tabindex="-1">OpenAI、Anthropic、Google 就 AI 安全密谈数周 <a class="header-anchor" href="#openai、anthropic、google-就-ai-安全密谈数周" aria-label="Permalink to &quot;OpenAI、Anthropic、Google 就 AI 安全密谈数周&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/7f1fdfbe5a7f.jpg" alt="配图"></p><p>OpenAI 确认已与 Anthropic、Google DeepMind 就 AI 安全议题进行数周磋商，与此同时特朗普团队淡化安全担忧，强调要跟上中国步伐。安全共识与政策松绑同时发生，说明监管路径仍高度不确定。对读者：做合规与风控规划时，别把「行业自律」当作稳定前提，需预留政策反转的应对方案。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/15/openai-anthropic-google-have-been-in-talks-on-ai-safety-for-weeks/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="aeo-创业公司-profound-估值破-10-亿美元-7-个月内再融-1-8-亿美元-d-轮" tabindex="-1">AEO 创业公司 Profound 估值破 10 亿美元，7 个月内再融 1.8 亿美元 D 轮 <a class="header-anchor" href="#aeo-创业公司-profound-估值破-10-亿美元-7-个月内再融-1-8-亿美元-d-轮" aria-label="Permalink to &quot;AEO 创业公司 Profound 估值破 10 亿美元，7 个月内再融 1.8 亿美元 D 轮&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/5600859e1df0.jpg" alt="配图"></p><p>面向 AI 搜索优化（AEO）的 Profound 完成 1.8 亿美元 D 轮，估值 18 亿美元，距上一轮 9600 万美元 C 轮不到七个月。资本对「让品牌被 AI 引用」这一新赛道给出极高溢价，也意味着 SEO 预算正在向 AEO 迁移。对读者：若做内容或增长，值得提前研究自家内容在 AI 答案中的引用率，这是新的流量入口。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/15/aeo-startup-profound-hits-unicorn-valuation-raises-180m-series-d-7-months-after-last-round/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="前-anthropic-早期员工与前-metr-coo-创业-融资-4000-万美元约束失控-ai-agent" tabindex="-1">前 Anthropic 早期员工与前 METR COO 创业，融资 4000 万美元约束失控 AI Agent <a class="header-anchor" href="#前-anthropic-早期员工与前-metr-coo-创业-融资-4000-万美元约束失控-ai-agent" aria-label="Permalink to &quot;前 Anthropic 早期员工与前 METR COO 创业，融资 4000 万美元约束失控 AI Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/4e2bc93fbf60.jpg" alt="配图"></p><p>两人创办的 AIUC（Artificial Intelligence Underwriting Company）完成 4000 万美元 A 轮，由 Ribbit Capital 领投。方向是为 AI Agent 提供承保式风险控制，把「Agent 闯祸谁负责」变成可定价的保险问题。对读者：企业部署 Agent 前，可关注这类第三方担保与审计服务，作为内部风控的补充层。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/09/15/early-anthropic-hire-former-metr-coo-have-found-a-way-to-rein-in-rogue-ai-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="salesforce-插件进入-claude-销售可在对话里做客户调研与-crm-更新" tabindex="-1">Salesforce 插件进入 Claude，销售可在对话里做客户调研与 CRM 更新 <a class="header-anchor" href="#salesforce-插件进入-claude-销售可在对话里做客户调研与-crm-更新" aria-label="Permalink to &quot;Salesforce 插件进入 Claude，销售可在对话里做客户调研与 CRM 更新&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/fc242445f380.jpg" alt="配图"></p><p>Anthropic 推出 Salesforce in Claude 插件，销售人员可直接在 Claude 内调研公司、准备通话、查看销售管道并起草 CRM 更新。这是把 AI 助手嵌入既有业务系统的典型路径，减少在工具间来回切换。对读者：评估 AI 助手时，优先看它能否直连你现有的 CRM/工单系统，集成深度往往比模型分数更影响实际效率。</p><p class="news-entry-source"><a href="https://claude.com/blog/salesforce-in-claude" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="meta-推出-one-订阅-把社交与-ai-用量打包定价" tabindex="-1">Meta 推出 One 订阅，把社交与 AI 用量打包定价 <a class="header-anchor" href="#meta-推出-one-订阅-把社交与-ai-用量打包定价" aria-label="Permalink to &quot;Meta 推出 One 订阅，把社交与 AI 用量打包定价&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/33bfa065834c.png" alt="配图"></p><p>Meta 上线 Meta One 订阅组合，将 Facebook、Instagram、WhatsApp 的独立订阅与额外 AI 用量打包，覆盖个人、创作者与企业多档，全球同步开放。官方强调核心体验与 Meta AI 仍免费，未来还将纳入 Edits、AI 眼镜等。对读者：社交平台的 AI 能力正从免费引流转向分层付费，重度用户需重新核算订阅成本。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/995453/meta-one-subscriptions-ai" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="claude-for-small-business-新增工作流、集成与培训计划" tabindex="-1">Claude for Small Business 新增工作流、集成与培训计划 <a class="header-anchor" href="#claude-for-small-business-新增工作流、集成与培训计划" aria-label="Permalink to &quot;Claude for Small Business 新增工作流、集成与培训计划&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Claude Blog</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/0568d42e68e5.jpg" alt="配图"></p><p>Anthropic 为中小企业推出新的 Claude 工作流与集成，并启动 Claude SMB Tour 下一阶段，帮助业主用 AI 运营和增长业务。大模型厂商正从开发者与大型企业向长尾中小客户下沉。对读者：中小团队可关注这类打包好的行业工作流，比自己从零搭 Agent 更快见效。</p><p class="news-entry-source"><a href="https://claude.com/blog/claude-for-small-business-launches-new-workflows-integrations-and-training-programs" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="simplisafe-新门铃让真人保安盯你家门口" tabindex="-1">SimpliSafe 新门铃让真人保安盯你家门口 <a class="header-anchor" href="#simplisafe-新门铃让真人保安盯你家门口" aria-label="Permalink to &quot;SimpliSafe 新门铃让真人保安盯你家门口&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/7b2989e6c6be.jpg" alt="配图"></p><p>SimpliSafe 发布 Video Doorbell Series 2，售价 199.99 美元，支持 2K 与双频 Wi-Fi，可搭配每月 49.99 美元起的 Active Guard 服务，用端侧 AI、云端视觉与人脸识别结合真人坐席主动响应。AI 加人工的混合安防成为消费级卖点。对读者：涉及家庭摄像与生物识别的产品，需重点确认数据留存与人工介入的隐私边界。</p><p class="news-entry-source"><a href="https://www.theverge.com/tech/995365/simplisafe-video-doorbell-series-2-virtual-guard-price-specs" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="zgcm-1-完全开放的高效数学与-agent-搜索基础模型" tabindex="-1">ZGCM-1：完全开放的高效数学与 Agent 搜索基础模型 <a class="header-anchor" href="#zgcm-1-完全开放的高效数学与-agent-搜索基础模型" aria-label="Permalink to &quot;ZGCM-1：完全开放的高效数学与 Agent 搜索基础模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">arXiv cs.AI</span><time datetime="2026-09-15">2026-09-15</time></p><p>arXiv 论文发布 ZGCM-1，一个从零训练的 7B 稠密基础模型，主打数据、系统与算法效率，支持 256K 上下文，通过内部思考与外部工具调用结合突破小模型容量限制。全开放训练配方对资源有限的团队有参考价值。对读者：若自建数学或检索类 Agent，可关注其架构与训练细节，小模型加工具链是可行路线。</p><p class="news-entry-source"><a href="https://arxiv.org/abs/2609.13356" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="google-发布-ai-与经济-atlas-新洞察" tabindex="-1">Google 发布 AI 与经济 ATLAS 新洞察 <a class="header-anchor" href="#google-发布-ai-与经济-atlas-新洞察" aria-label="Permalink to &quot;Google 发布 AI 与经济 ATLAS 新洞察&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google AI Blog</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/aa178a2f612f.png" alt="配图"></p><p>Google 将 ATLAS 的百万级全球数据点转化为可交互、开放访问的体验，用于观察 AI 对经济的影响。这类公开数据集对判断 AI 落地节奏与区域差异有参考意义。对读者：做市场或投资判断时，可把此类开放数据纳入信息源，减少只凭厂商口径做决策。</p><p class="news-entry-source"><a href="https://blog.google/innovation-and-ai/technology/ai/ai-economy-atlas-september-2026/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="cloudflare-workers-支持按单个-worker-精细授权" tabindex="-1">Cloudflare Workers 支持按单个 Worker 精细授权 <a class="header-anchor" href="#cloudflare-workers-支持按单个-worker-精细授权" aria-label="Permalink to &quot;Cloudflare Workers 支持按单个 Worker 精细授权&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Cloudflare Blog</span><time datetime="2026-09-15">2026-09-15</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-09/0a9dcf205cbb.png" alt="配图"></p><p>Cloudflare 允许把访问权限细化到单个 Worker，并分配更窄的 Developer Platform 角色，使队友、CI Token 与 Agent 只拿到调试、部署或监控所需的最小权限。Agent 参与部署后的权限治理成为刚需。对读者：给 CI 与自动化 Agent 分配凭证时，应遵循最小权限原则，避免一把全权限 Token 长期流通。</p><p class="news-entry-source"><a href="https://blog.cloudflare.com/workers-granular-authorization/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div>',8)])])}const g=a(s,[["render",o]]);export{m as __pageData,g as default};
